SELECT id,any(name) AS name,toString(month) AS month,round(sum(v),2) AS openrank FROM (SELECT l.id AS id,any(l.name) AS name,e.platform AS platform,e.repo_id AS repo_id,any(e.repo_name) AS repo_name,e.created_at AS month,any(e.openrank) AS v FROM global_openrank e INNER JOIN (SELECT id,name,platform,entity_id,entity_type FROM flatten_labels WHERE type='Foundation') l ON (l.entity_id=e.repo_id AND l.entity_type='Repo' AND l.platform=e.platform) OR (l.entity_id=e.org_id AND l.entity_type='Org' AND l.platform=e.platform) WHERE e.platform IN ('GitHub','Gitee','GitLab','AtomGit') AND e.type='Repo' AND e.created_at>='2025-07-01' AND e.created_at<'2026-07-01' GROUP BY l.id,e.platform,e.repo_id,e.created_at) GROUP BY id,month ORDER BY id,month SETTINGS max_execution_time=80,max_threads=4;